"""Independent verification of (FR), Lemma M machine, B_c bound, stale-row claims.

Reads solver table output: line q (0-indexed) has f(q,0..rmax).
"""
import sys
from itertools import count

TAB = "scratch/table_300_700.txt"
f = []
for line in open(TAB):
    f.append([int(x) for x in line.split()])
QMAX = len(f) - 1
RMAX = len(f[0]) - 1
print(f"table q<={QMAX}, r<={RMAX}")

def F(x, r):
    """first-clause-extended f: F(x,r)=f(x,r) for x>=r else f(x,x)"""
    return f[x][r] if x >= r else f[x][x]

def mex_pos(S):
    """mex over positive integers"""
    S = set(S)
    m = 1
    while m in S:
        m += 1
    return m

def mex_nonneg(S):
    S = set(S)
    m = 0
    while m in S:
        m += 1
    return m

# ---------- sanity: cross-check recurrence of MISSION s2 against solver ----------
bad_rec = 0
for q in range(0, QMAX + 1):
    for r in range(0, min(q, RMAX) + 1):
        if r > q:
            exp = f[q][q]
        elif f[q - 1][r] < q:
            exp = f[q - 1][r]
        else:
            S = {F(x, r) for x in range(q)} | {f[q][b] for b in range(r)}
            exp = mex_pos(S)
        if exp != f[q][r]:
            bad_rec += 1
            if bad_rec < 5:
                print("REC MISMATCH", q, r, exp, f[q][r])
print("recurrence-vs-solver mismatches:", bad_rec)

# ---------- B_c bound: f(q,c) <= q + c + 1 ----------
bad_bound = 0
for q in range(0, QMAX + 1):
    for c in range(0, min(q, RMAX) + 1):
        if f[q][c] > q + c + 1:
            bad_bound += 1
print("bound f(q,c)<=q+c+1 violations:", bad_bound)

# ---------- define B, u, p, N for rows c <= RMAX from data ----------
def row_profile(c, qmax=QMAX):
    """returns dict: stale?, q0/deathq, N, p, u, B list on x=0..xmax"""
    # B_c(x) = f(c+x,c)-(c+x), defined iff f(c+x,c) >= c+x
    xs = range(0, qmax - c + 1)
    B = {}
    for x in xs:
        q = c + x
        v = f[q][c] - q
        if v >= 0:
            B[x] = v
        else:
            break  # undefined from here on (claimed); verify below
    # check undefined-forever
    for x in range(max(B) + 1 if B else 0, qmax - c + 1):
        q = c + x
        if f[q][c] >= q:
            raise RuntimeError(f"row {c}: undefined then defined at x={x}")
    xmax = qmax - c
    # stale iff exists q0 with f(q0,c) <= q0 ... B stops at some x
    last_defined = max(B) if B else -1
    q_last = c + last_defined
    # check f(q,c)=q0 for all q>q_last
    stale = (last_defined < xmax)
    if stale:
        q0 = q_last
        for q in range(q0 + 1, qmax + 1):
            assert f[q][c] == f[q0][c], (c, q)
        # check f(q0,c) == q0
        assert f[q0][c] == q0, (c, q0, f[q0][c])
        N = q0 + 1
        p = 1
        u = N - c
    else:
        # live: find least eventual period p and least onset u
        p = None
        for cand in range(1, 61):
            # least onset for cand
            u_cand = None
            for x0 in range(0, xmax - cand + 1):
                if all(B.get(x, None) == B.get(x + cand, None)
                       for x in range(x0, xmax - cand + 1)):
                    u_cand = x0
                    break
            if u_cand is not None:
                p = cand
                u = u_cand
                break
        assert p is not None, c
        N = c + u
    return dict(c=c, stale=stale, N=N, p=p, u=u, B=B, xmax=xmax)

profiles = {}
for c in range(0, RMAX + 1):
    profiles[c] = row_profile(c)

# consistency of conventions: for live rows f(q,c) > q everywhere (B defined everywhere)
bad_live = 0
for c in range(0, RMAX + 1):
    pr = profiles[c]
    if not pr["stale"]:
        if len(pr["B"]) != pr["xmax"] + 1:
            bad_live += 1
print("live rows with some undefined B in range:", bad_live)

# stale-row claims [C0029]
bad_stale = 0
for c in range(0, RMAX + 1):
    pr = profiles[c]
    if pr["stale"]:
        q0 = pr["N"] - 1
        if q0 > 2 * c + 1 or f[q0][c] != q0:
            bad_stale += 1
            print("stale claim fail", c, q0)
print("stale-row claim violations:", bad_stale)

# ---------- (FR) check ----------
bad_FR = 0
FR_steps = 0
bad_subset = 0
for r in range(1, RMAX + 1):
    a = 0
    trail = []  # list of L values for reached a
    while r + a <= QMAX:
        q = r + a
        L = f[q][r] - q
        if L < 0:
            break  # not reached (row terminated earlier) -- shouldn't happen
        # build S and S_q directly
        S = {F(x, r) for x in range(q)} | {f[q][b] for b in range(r)}
        if mex_pos(S) != f[q][r]:
            bad_FR += 1
            print("mex_pos mismatch", r, a)
        if not set(range(1, q)) <= S:
            bad_subset += 1
        Sq = {s - q for s in S if s >= q}
        W = set()
        for c in range(r):
            x = a + r - c
            if x <= profiles[c]["xmax"]:
                bc = profiles[c]["B"].get(x, None)
                if bc is not None:
                    W.add(bc)
            else:
                bc = f[c + x][c] - (c + x) if c + x <= QMAX else None
                if bc is not None and bc >= 0:
                    W.add(bc)
        # V'
        Vp = set()
        for c in range(r):
            b0 = profiles[c]["B"].get(0)
            if b0 is not None:
                v = b0 - (r - c) - a
                if v >= 0:
                    Vp.add(v)
        T = {trail[a - i] - i for i in range(1, a + 1)} - set()
        T = {t for t in T if t >= 0}
        if mex_nonneg(Sq) != L:
            bad_FR += 1
            print("FR mismatch", r, a, mex_nonneg(Sq), L)
        if mex_nonneg(W | Vp | T) != L:
            bad_FR += 1
            print("FR(WVT) mismatch", r, a)
        FR_steps += 1
        trail.append(L)
        if L == 0:
            break
        a += 1
print("FR steps checked:", FR_steps, "FR violations:", bad_FR,
      "{1..q-1} subset S violations:", bad_subset)

# ---------- machine (M) check ----------
bad_M = 0
M_steps = 0
bad_inv = 0
for r in range(1, RMAX + 1):
    # m_r
    mx = max(max(profiles[c]["B"].values()) for c in range(r))
    m_r = 1 + mx
    if m_r > r + 1:
        bad_inv += 1
        print("m_r bound fail", r, m_r)
    H = set()
    for c in range(r):
        b0 = profiles[c]["B"].get(0)
        if b0 is not None:
            v = b0 - (r - c)
            if v >= 0:
                H.add(v)
    a = 0
    while r + a <= QMAX:
        q = r + a
        L = f[q][r] - q
        if L < 0:
            break
        Vs = set()
        for c in range(r):
            x = a + r - c
            bc = None
            if x <= profiles[c]["xmax"]:
                bc = profiles[c]["B"].get(x, None)
            else:
                v = f[c + x][c] - (c + x)
                bc = v if v >= 0 else None
            if bc is not None:
                Vs.add(bc)
        k = mex_nonneg(Vs | H)
        if k != L:
            bad_M += 1
            if bad_M < 5:
                print("machine mismatch", r, a, k, L)
        if not H <= set(range(m_r)):
            bad_inv += 1
            if bad_inv < 5:
                print("H invariant fail", r, a, H, m_r)
        if k > m_r:
            bad_inv += 1
        M_steps += 1
        if k == 0:
            break
        H = {h - 1 for h in H if h >= 1} | {k - 1}
        a += 1
print("machine steps checked:", M_steps, "machine violations:", bad_M,
      "invariant violations:", bad_inv)
"}

