"""Test the CLAIM: a -> V''(a) is q_r-periodic for all a >= max(sigma_r, 0).

Part 1: direct, from solver table f(q,r), rows r=1..200 (incl. boundary r=1,2).
Part 2: from census_50000.tsv exact tails, rows r up to 50000 (exhaustive to 3000,
        sampled above, incl. all anomalous period-6/8/9 rows).
Also: show the threshold is sharp (periodicity fails at a = max(sigma_r,0)-1 often).
"""
import math
from functools import reduce

# ---------------- Part 1: direct from table ----------------
f = []
for line in open("scratch/table_300_700.txt"):
    f.append([int(x) for x in line.split()])
QMAX = len(f) - 1
RMAX = len(f[0]) - 1

def row_profile(c):
    B = {}
    for x in range(0, QMAX - c + 1):
        q = c + x
        v = f[q][c] - q
        if v >= 0:
            B[x] = v
        else:
            break
    xmax = QMAX - c
    last = max(B) if B else -1
    stale = last < xmax
    if stale:
        q0 = c + last
        N = q0 + 1
        p = 1
    else:
        p = u = None
        for cand in range(1, 61):
            for x0 in range(0, xmax - cand + 1):
                if all(B.get(x) == B.get(x + cand) for x in range(x0, xmax - cand + 1)):
                    p, u = cand, x0
                    break
            if p is not None:
                break
        N = c + u
    return dict(N=N, p=p, stale=stale, xmax=xmax)

profiles = {c: row_profile(c) for c in range(0, RMAX + 1)}

def Vpp(r, a):
    """V''(a) directly from raw f values (not from profiles)."""
    out = set()
    for c in range(r):
        q = c + (a + r - c)  # = r + a
        if q > QMAX:
            return None
        v = f[q][c] - q
        if v >= 0:
            out.add(v)
    return frozenset(out)

bad = 0
checked_r = 0
sharp = 0
first_fail = None
for r in range(1, 201):
    q_r = 1
    for c in range(r):
        q_r = q_r * profiles[c]["p"] // math.gcd(q_r, profiles[c]["p"])
    sigma = max(profiles[c]["N"] for c in range(r)) - r
    start = max(sigma, 0)
    a_max = min(QMAX - r, start + 3 * q_r + 40)
    if a_max < start:
        continue
    checked_r += 1
    for a in range(start, a_max + 1):
        v1 = Vpp(r, a)
        v2 = Vpp(r, a + q_r) if a + q_r <= QMAX - r else None
        if v2 is None:
            break
        if v1 != v2:
            bad += 1
            if first_fail is None:
                first_fail = (r, a, q_r, sigma, sorted(v1), sorted(v2))
    # sharpness: does it fail just below the threshold?
    if start >= 1:
        v1 = Vpp(r, start - 1)
        v2 = Vpp(r, start - 1 + q_r) if start - 1 + q_r <= QMAX - r else None
        if v1 is not None and v2 is not None and v1 != v2:
            sharp += 1
print(f"Part 1 (direct, r=1..200): r-checked={checked_r} failures={bad} "
      f"threshold-sharp rows={sharp} first_fail={first_fail}")

# boundary r=1, r=2 explicit
for r in (1, 2):
    q_r = 1
    for c in range(r):
        q_r = q_r * profiles[c]["p"] // math.gcd(q_r, profiles[c]["p"])
    sigma = max(profiles[c]["N"] for c in range(r)) - r
    print(f"  r={r}: q_r={q_r} sigma_r={sigma} N(c)={[profiles[c]['N'] for c in range(r)]} "
          f"p_c={[profiles[c]['p'] for c in range(r)]}")
    print("    V''(a) for a=0..4:", [sorted(Vpp(r, a)) for a in range(5)])

# ---------------- Part 2: from census (exact tails), r up to 50000 ----------------
rows = []
for line in open("census_50000.tsv"):
    if line.startswith("#") or line.startswith("r\t"):
        continue
    fl = line.rstrip("\n").split("\t")
    r = int(fl[0]); cls = fl[1]; per = int(fl[2]); N = int(fl[3])
    dvals = None if fl[4] == "-" else [int(x) for x in fl[4].split(",")]
    rows.append((r, cls, per, N, dvals))
assert rows[0][0] == 0 and len(rows) == 50001

def tail_B(c_idx, x):
    """B_c(x) from census tail; None = undefined."""
    r_, cls, per, N, dvals = rows[c_idx]
    u = N - r_
    if x < u:
        return "PRE"      # preperiod: not used for a >= sigma_r
    if cls == "stale":
        return None
    return dvals[(x - u) % per]

def p_of(c_idx):
    return 1 if rows[c_idx][1] == "stale" else rows[c_idx][2]

def N_of(c_idx):
    return rows[c_idx][3]

bad2 = 0
first2 = None
checked = 0
# exhaustive r <= 3000 plus a spread and all anomaly neighborhoods
test_r = set(range(1, 3001))
test_r |= set(range(3000, 50001, 251))
anom = [6541, 8767, 11036, 18583, 18718, 28109, 33597, 46110]
for a_ in anom:
    test_r |= set(range(max(1, a_ - 3), a_ + 6))
test_r = sorted(x for x in test_r if 1 <= x <= 50000)
for r in test_r:
    q_r = 1
    mxN = 0
    for c in range(r):
        q_r = q_r * p_of(c) // math.gcd(q_r, p_of(c))
        mxN = max(mxN, N_of(c))
    sigma = mxN - r
    start = max(sigma, 0)
    # check V''(a) == V''(a+q_r) for a in [start, start + 2*q_r + 20]
    for a in range(start, start + 2 * q_r + 21):
        v1 = set(); v2 = set()
        ok = True
        for c in range(r):
            x1 = a + r - c
            b1 = tail_B(c, x1)
            if b1 == "PRE":
                ok = False; break
            if b1 is not None:
                v1.add(b1)
            x2 = a + q_r + r - c
            b2 = tail_B(c, x2)
            if b2 == "PRE":
                ok = False; break
            if b2 is not None:
                v2.add(b2)
        if not ok:
            bad2 += 1
            if first2 is None:
                first2 = (r, a, "preperiod leak")
            continue
        if v1 != v2:
            bad2 += 1
            if first2 is None:
                first2 = (r, a, sorted(v1), sorted(v2))
    checked += 1
print(f"Part 2 (census, {checked} rows up to r=50000): failures={bad2} first={first2}")

# sharpness on part 2 sample: failure at a = start-1 (when start >= 1)
sharp2 = 0
for r in test_r[:400]:
    q_r = 1; mxN = 0
    for c in range(r):
        q_r = q_r * p_of(c) // math.gcd(q_r, p_of(c)); mxN = max(mxN, N_of(c))
    start = max(mxN - r, 0)
    if start < 1:
        continue
    a = start - 1
    v1 = set(); v2 = set(); ok = True
    for c in range(r):
        b1 = tail_B(c, a + r - c); b2 = tail_B(c, a + q_r + r - c)
        if b1 == "PRE" or b2 == "PRE":
            ok = False; break
        if b1 is not None: v1.add(b1)
        if b2 is not None: v2.add(b2)
    if ok and v1 != v2:
        sharp2 += 1
print(f"  sharpness (first 400 sampled r): {sharp2} rows fail at a = sigma_r - 1")
", "path": "scratch/verify_claim.py"}

