{"content": "#!/usr/bin/env python3
"""Part 2: claim test on census_50000.tsv exact tails (independently cross-validated
against raw solver f-values for r <= 300). Exhaustive r <= 2000, stride sample and
all anomaly rows (periods 6/8/9) neighborhoods up to r = 50000."""
import math, time

rows = []
for line in open("census_50000.tsv"):
    if line.startswith("#") or line.startswith("r\t"):
        continue
    fl = line.rstrip("\n").split("\t")
    rows.append((fl[1], int(fl[2]), int(fl[3]),
                 None if fl[4] == "-" else [int(x) for x in fl[4].split(",")]))
assert len(rows) == 50001

def tail(c, x):
    cls, per, N, dv = rows[c]
    u = N - c
    if x < u: return "PRE"
    if cls == "stale": return None
    return dv[(x - u) % per]

def check_row(r, a_list):
    cls_r, per_r, N_r, _ = rows[r]
    q_r = 1; mxN = 0
    for c in range(r):
        cls, per, N, _ = rows[c]
        p = 1 if cls == "stale" else per
        q_r = q_r * p // math.gcd(q_r, p)
        if N > mxN: mxN = N
    sigma = mxN - r
    start = max(sigma, 0)
    bad = []
    for a in a_list:
        v1 = set(); v2 = set(); leak = False
        for c in range(r):
            b1 = tail(c, a + r - c)
            b2 = tail(c, a + q_r + r - c)
            if b1 == "PRE" or b2 == "PRE":
                leak = True; break
            if b1 is not None: v1.add(b1)
            if b2 is not None: v2.add(b2)
        if leak or v1 != v2:
            bad.append((a, sorted(v1), sorted(v2), leak))
    return q_r, sigma, bad

t0 = time.time()
test = []
for r in range(1, 2001):
    test.append((r, "exh"))
for r in range(2050, 50001, 499):
    test.append((r, "str"))
anom = [6541, 8767, 11036, 18583, 18718, 28109, 33597, 46110]
for a_ in anom:
    for d in range(-4, 7):
        if 1 <= a_ + d <= 50000:
            test.append((a_ + d, "anom"))
test = sorted(set(test))

nfail = 0; first = None; nrow = 0
for r, kind in test:
    q_r_ = None
    if kind == "exh":
        a_list = None  # filled below
    cls_r, per_r, N_r, _ = rows[r]
    q_r = 1; mxN = 0
    for c in range(r):
        cls, per, N, _ = rows[c]
        p = 1 if cls == "stale" else per
        q_r = q_r * p // math.gcd(q_r, p)
        if N > mxN: mxN = N
    start = max(mxN - r, 0)
    if kind == "exh":
        a_list = list(range(start, start + q_r + 11))
    elif kind == "str":
        a_list = list(range(start, start + 2 * q_r + 7))
    else:
        a_list = list(range(start, start + 6)) + list(range(start + q_r - 2, start + q_r + 4))
    q_r2, sigma, bad = check_row(r, a_list)
    nrow += 1
